#import <Foundation/Foundation.h>
#include "../Includes.h"

#define AddDinosaur(DisplayName,  EntityName,  BlueprintString) Dinosaurs.push_back({DisplayName, EntityName, BlueprintString})

string DinoSpawn::GetDinoEntityName(string DisplayName){
    for(const CreatureIDStruct& currentDinosaur : Dinosaurs){
        if(currentDinosaur.DisplayName == DisplayName){
            return currentDinosaur.EntityName;
        }
    }
    return "";
}
string DinoSpawn::GetDinoBlueprintString(string DisplayName){
    for(const CreatureIDStruct& currentDinosaur : Dinosaurs){
        if(currentDinosaur.DisplayName == DisplayName){
            return currentDinosaur.BlueprintString;
        }
    }
    return "";
}
