void DinoSpawn::DrawMenu(){
    InitializeDinoList();
    
    const char* CommandNames[] = {GetMenuText("Spawn Actor"), GetMenuText("Spawn Actor Tamed"), GetMenuText("GMSummon"), GetMenuText("Spawn Actor Spread"), GetMenuText("Destroy Actors")};
    static int CommandNameIndex = 0;
    static string SelectedDino = "";
    
    ImGui::Combo("Dino Commands", &CommandNameIndex, CommandNames, IM_ARRAYSIZE(CommandNames));
    
    if(SelectedDino == "")
    {
        strcpy(textfieldBuffer, textField.text.UTF8String);
        string DisplayString = string("InputText: ") + textfieldBuffer;
        ImGui::Button(DisplayString.c_str(), ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20));
        if(ImGui::IsItemHovered()){
            [textField becomeFirstResponder];
        } else{
            [textField resignFirstResponder];
        }
        
        ImGui::PushStyleVar(ImGuiStyleVar_ChildBorderSize, 0);
        ImGui::PushStyleVar(ImGuiStyleVar_ScrollbarSize, 20);
        
        ImGui::BeginChild("ChildMain", ImVec2(ImGui::GetContentRegionAvailWidth()-20, 160), true, ImGuiWindowFlags_None);
        string FilterString = textfieldBuffer;
        ImGui::Indent();
        
        
        for(int i = 0; i < Dinosaurs.size(); i++){
            CreatureIDStruct MyDinosaur = Dinosaurs[i];
            if(utils.containsIgnoreCase(MyDinosaur.DisplayName, FilterString)){
                ImGui::PushItemWidth(200);
                
                ImGui::Text("%s", MyDinosaur.DisplayName.c_str());
                
                ImGui::PopItemWidth();
                
                ImGui::SameLine(200);

                ImGui::PushID(i);
                if(ImGui::Button("Select", ImVec2(100, ImGui::GetFrameHeight()))){
                    SelectedDino = MyDinosaur.DisplayName;
                }
                ImGui::PopID();
            }
        }
        
        ImGui::Unindent();
        ImGui::EndChild();
        
        ImGui::PopStyleVar(2);
        
        
    }
    else
    {
        string SelectedDinoButtonText = "Selected Dino: " + SelectedDino;
        if(ImGui::Button(SelectedDinoButtonText.c_str(), ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20))){
            SelectedDino = "";
            textField.text = @"";
        }
        /*
         const char* CommandNames[] = {"Spawn Actor", "Spawn Actor Tamed", "GMSummon", "Spawn Actor Spread", "Destroy Actors"};
         static int CommandNameIndex = 0;
         */
        if(CommandNameIndex == 0) //Spawn Actor
        {
            if(ImGui::Button("Spawn Actor", ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20)))
            {
                functions.ExecuteConsoleCommand(utils.string_format("SpawnActor \"%s\" 0 0 200", GetDinoBlueprintString(SelectedDino).c_str()));
            }
        }
        else if(CommandNameIndex == 1) //Spawn Actor Tamed
        {
            if(ImGui::Button("Spawn Actor Tamed", ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20)))
            {
                functions.ExecuteConsoleCommand(utils.string_format("SpawnActorTamed \"%s\" 0 0 200", GetDinoBlueprintString(SelectedDino).c_str()));
            }
        }
        else if(CommandNameIndex == 2) //GMSummon
        {
            static int Level = 1;
            ImGui::SliderInt("Dino Level", &Level, 1, 600);
            
            if(Level < 380 && Level > 340){
                Level = 360;
            }
            
            if(Level < 560 && Level > 520){
                Level = 540;
            }
            
            if(ImGui::Button("GMSummon", ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20)))
            {
                functions.ExecuteConsoleCommand(utils.string_format("GMSummon \"%s\" %d", GetDinoEntityName(SelectedDino).c_str(), Level));
            }
            if(ImGui::Button("GMSummon Custom Level", ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20)))
            {
                UIAlertController *alertController = [UIAlertController alertControllerWithTitle:@"GMSummon"
                                                                                                 message:@"Input Spawn Level"
                                                                                          preferredStyle:UIAlertControllerStyleAlert];
                
                [alertController addTextFieldWithConfigurationHandler:^(UITextField *textField) {textField.placeholder = @"Spawn Level";}];
                
                UIAlertAction* Send = AlertAction(@"GMSummon"){
                    UITextField *textField = alertController.textFields.firstObject;
                    int SpawnLevel = [textField.text intValue];
                    functions.ExecuteConsoleCommand(utils.string_format("GMSummon \"%s\" %d", GetDinoEntityName(SelectedDino).c_str(), SpawnLevel));
                    // ConsoleCommand([NSString stringWithFormat:@"GMSummon \"%@\" %d", [NSString stringWithUTF8String:GetEntityName(SelectedDino).c_str()], DinosaurLevel]);
                }];
                UIAlertAction* Cancel = AlertAction(@"Cancel"){}];
                
                [alertController addAction:Send];
                [alertController addAction:Cancel];
                [[UIApplication sharedApplication].windows[0].rootViewController presentViewController:alertController animated:YES completion:nil];
            }
        }
        else if(CommandNameIndex == 3) //Spawn actor spread
        {
            static int SpawnAmmount = 1;
            static float SpawnRange = 5000;
            ImGui::SliderInt("Spawn Ammount", &SpawnAmmount, 1, 1000);
            ImGui::SliderFloat("Spawn Range", &SpawnRange, 100, 4000000);
            if(ImGui::Button("Spawn Actor Spread", ImVec2(ImGui::GetContentRegionAvailWidth() - 10, 20)))
            {
